const fs   = require('fs');
const vars = $('Load Project').first().json;
const form = $input.first().json;

const templateNum   = parseInt(form['TEMPLATE NUMBER'], 10) || 1;
const titleOverride = (form['EPISODE TITLE OVERRIDE'] || '').trim();
const generationNum = 1;
const episodeTitle  = titleOverride || vars.topic;

const templateNames = {
  1: 'Revelation Shot',
  2: 'Explorer Face',
  3: 'Split Reveal',
  4: 'Mystery Object',
  5: 'Location Atmosphere',
};

const systemPrompt = fs.readFileSync(
  '/Users/jneal/n8n_projects/ruins_untold_system_prompts/thumbnail_agent.md',
  'utf-8'
);

const fullPrompt = systemPrompt
  + '\n\n---\n\nTemplate: ' + templateNum
  + ' — ' + (templateNames[templateNum] || 'Unknown')
  + '\nEpisode title: ' + episodeTitle;

const thumbnailPromptPath = vars.projectDir + '/scripts/thumbnail_prompt_' + generationNum + '.json';

return [{ json: {
  ...vars,
  thumbnailTemplate:      templateNum,
  thumbnailEpisodeTitle:  episodeTitle,
  generationNum,
  thumbnailPromptPath,
  claudeBody: JSON.stringify({ prompt: fullPrompt }),
} }];

const fs   = require('fs');
const vars = $('Build Thumbnail Prompt').first().json;
const resp = $input.first().json;
const raw  = resp.output || '';

const jsonMatch = raw.match(/```json\n([\s\S]*?)\n```/);
let thumbnailJson = null;
if (jsonMatch) {
  try { thumbnailJson = JSON.parse(jsonMatch[1]); } catch (e) {}
}

const textMatch = raw.match(/>\s*Text overlay suggestion:\s*(.+)/);
const genMatch  = raw.match(/>\s*To generate:\s*(.+)/);

const pkg = {
  episode_title:  vars.thumbnailEpisodeTitle,
  template:       vars.thumbnailTemplate,
  generation:     vars.generationNum,
  generated_at:   new Date().toISOString(),
  thumbnail_json: thumbnailJson,
  text_overlay:   textMatch ? textMatch[1].trim() : '',
  kie_command:    genMatch  ? genMatch[1].trim()  : '',
  raw_output:     raw,
};

fs.writeFileSync(vars.thumbnailPromptPath, JSON.stringify(pkg, null, 2));

console.log('Thumbnail prompt saved:', vars.thumbnailPromptPath);
if (pkg.text_overlay) console.log('Text overlay:', pkg.text_overlay);

return [{ json: {
  slug:                 vars.slug,
  topic:                vars.topic,
  projectDir:           vars.projectDir,
  summaryPath:          vars.summaryPath,
  renderCompletePath:   vars.renderCompletePath,
  thumbnailPromptPath:  vars.thumbnailPromptPath,
  thumbnailTextOverlay: pkg.text_overlay,
  thumbnailKieCommand:  pkg.kie_command,
  generationNum:        vars.generationNum,
} }];

